// Engine v2 (core/scan-engine-v2.js + core/doc-text.js), run through the app's
// own scan flow against the mock Worker. Only INVENTED documents: a PDF and a
// Word .doc are generated byte by byte below.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import { createScannerSandbox, toPrediction, browserMimeType } from '../lib/app-sandbox.mjs';
import { createMockFetch } from '../lib/mock-fetch.mjs';
import { recordingFetch } from '../run-current.mjs';
import { makePdf, makeDoc, SYNTH_LINES } from './synthetic-docs.mjs';

const require = createRequire(import.meta.url);
const HERE = path.dirname(fileURLToPath(import.meta.url));
const REPO = path.resolve(HERE, '../../..');
const FIX = path.join(HERE, '..', 'fixtures');
const refData = JSON.parse(fs.readFileSync(path.join(FIX, 'synthetic-ref.json'), 'utf8'));
const extraction = JSON.parse(fs.readFileSync(path.join(FIX, 'synthetic-extraction.json'), 'utf8'));
const extractionV2 = JSON.parse(fs.readFileSync(path.join(FIX, 'synthetic-extraction-v2.json'), 'utf8'));
const { docLegacyToText } = require(path.join(REPO, 'core/doc-text.js'));
const LINES = SYNTH_LINES;

function v2Sandbox(v2 = {}) {
  const mock = createMockFetch({ refData, extraction, extractionV2 });
  const fetch = recordingFetch(mock);
  return { fetch, mock, sb: createScannerSandbox({ repoRoot: REPO, fetch, jwt: 'test.jwt.value', refData, engine: 'v2', v2 }) };
}
const aiCalls = fetch => fetch.calls.filter(c => c.path === '/v1/ai/messages');

test('doc-text: reads the piece table of a Word 97 file, refuses what it cannot read', () => {
  const txt = docLegacyToText(makeDoc(LINES.join('\n')));
  assert.match(txt, /Transport order SYN-0001/);
  assert.match(txt, /Gamma Warehouse, Samplepolis/);
  assert.equal(txt.split('\n').length, LINES.length);
  assert.throws(() => docLegacyToText(Buffer.from('%PDF-1.4 not a doc')), /not an OLE2/);
  assert.throws(() => docLegacyToText(makeDoc('x', { password: true })), /password/);
});

test('v2: PDF with a text layer → ONE structured-output call carrying text, not the PDF', async () => {
  const { fetch, mock, sb } = v2Sandbox();
  const r = await sb.scanFile(new File([makePdf(LINES)], 'synthetic-order.pdf', { type: browserMimeType('x.pdf') }));
  assert.equal(r.status, 'ok', r.error);
  const ai = aiCalls(fetch);
  assert.equal(ai.length, 1);
  assert.equal(ai[0].tools, 0);
  const body = mock.calls.filter(c => c.body).at(-1).body;
  assert.equal(body.output_config.format.type, 'json_schema');
  assert.deepEqual(body.system[0].cache_control, { type: 'ephemeral' });
  const content = body.messages[0].content;
  assert.ok(content.every(c => c.type === 'text'), 'text mode sends no document block');
  assert.match(content[0].text, /SYN-0001/);
  assert.match(content[0].text, /CLIENT CANDIDATES[\s\S]*ACME FROZEN FOODS GMBH/);
  assert.equal(r.parsed._v2.input, 'text');
});

test('v2: matching in code over all records, pallet type and stop pallets reach the form', async () => {
  const { sb } = v2Sandbox();
  const r = await sb.scanFile(new File([makePdf(LINES)], 'synthetic-order.pdf', { type: browserMimeType('x.pdf') }));
  const p = toPrediction(r, sb.constants().F);
  assert.equal(p.client_id, 'recSynthClient0001');                 // by name — the answer carried no id
  assert.equal(p.reference, 'SYN-0001');
  assert.equal(p.pallet_type, 'EUR');
  assert.equal(p.temperature_c, -18);
  assert.equal(p.direction, 'Import');                             // derived from stop countries
  assert.equal(p.price, 1500);
  assert.deepEqual(p.stops.map(s => [s.type, s.location_id, s.date, s.pallets, s.country]), [
    ['loading', 'recSynthLoc000001', '2031-01-10', 20, 'DE'],
    ['delivery', 'recSynthLoc000002', '2031-01-13', 20, 'GR'],   // single delivery inherits the total
  ]);
  assert.ok(p.confidence.reference > 0.9);
});

test('v2: legacy .doc passes the gate and is sent as text', async () => {
  const { fetch, sb } = v2Sandbox();
  const r = await sb.scanFile(new File([makeDoc(LINES.join('\n'))], 'synthetic-order.doc', { type: browserMimeType('x.doc') }));
  assert.equal(r.status, 'ok', r.error);
  assert.equal(aiCalls(fetch).length, 1);
  assert.equal(r.parsed._v2.input, 'text');
  assert.equal(r.parsed._v2.why, 'doc');
});

test('v2: PDF without a text layer falls back to sending the PDF itself', async () => {
  const { sb } = v2Sandbox();
  const r = await sb.scanFile(new File([Buffer.from('%PDF-1.4\n% no text\n%%EOF\n')], 'scan.pdf', { type: browserMimeType('x.pdf') }));
  assert.equal(r.status, 'ok', r.error);
  assert.equal(r.parsed._v2.input, 'pdf');
});

test('v2: an unreadable .doc says so instead of producing an empty order', async () => {
  const { fetch, sb } = v2Sandbox();
  const r = await sb.scanFile(new File([Buffer.from('garbage bytes, not a word file')], 'broken.doc', { type: browserMimeType('x.doc') }));
  assert.equal(r.status, 'error');
  assert.match(r.error, /Word/);
  assert.equal(aiCalls(fetch).length, 0);
});

test('v2 switch off (default): .doc still refused, v1 flow unchanged', async () => {
  const fetch = recordingFetch(createMockFetch({ refData, extraction, extractionV2 }));
  const sb = createScannerSandbox({ repoRoot: REPO, fetch, jwt: 'x.y.z', refData });
  const r = await sb.scanFile(new File([makeDoc('x')], 'a.doc', { type: browserMimeType('x.doc') }));
  assert.equal(r.status, 'rejected');
});

test('credit exhausted (Worker 402): the dispatcher reads the Worker message, no retries', async () => {
  const mock = createMockFetch({ refData, extraction, extractionV2 });
  const f402 = async (url, init) => new URL(url).pathname === '/v1/ai/messages'
    ? new Response(JSON.stringify({ error: 'Εξαντλήθηκε η πίστωση AI — ενημερώστε τον διαχειριστή' }), { status: 402 })
    : mock(url, init);
  const fetch = recordingFetch(f402);
  const sb = createScannerSandbox({ repoRoot: REPO, fetch, jwt: 'x.y.z', refData, engine: 'v2' });
  const r = await sb.scanFile(new File([makeDoc(LINES.join('\n'))], 'a.doc', { type: browserMimeType('x.doc') }));
  assert.equal(r.status, 'error');
  assert.match(r.error, /πίστωση AI/);
  assert.equal(aiCalls(fetch).length, 1);
});

test('v2 number parsing: European separators, signs incl. Unicode minus', async () => {
  const vm = await import('node:vm');
  const ctx = {}; vm.createContext(ctx);
  vm.runInContext(fs.readFileSync(path.join(REPO, 'core/scan-engine-v2.js'), 'utf8') + ';globalThis.__n = _sv2Num;', ctx);
  const n = ctx.__n;
  for (const [inp, out] of [['22.500', 22500], ['2.200,00', 2200], ['21,000', 21000], ['8.5', 8.5], ['-18', -18], ['+4', 4],
    ['\u221218', -18], ['\u201318 C', -18], ['0', 0], ['', null], ['abc', null], ['3 500,00 kg', 3500]]) {
    assert.equal(n(inp), out, JSON.stringify(inp));
  }
});
